input.value:
fetch logs, from: now()-10m
| filter project == "TonyStark"   // ✏️ change "TonyStark" to your project name
| fieldsAdd source = if(isNotNull(flow.type), "NetFlow",
    else: if(isNotNull(log.file.name), concat("File: ", log.file.name),
    else: if(isNotNull(appname), "Syslog", else: "Other")))
| summarize records = count(), by: { source }
| sort records desc

// Query-time parsing: works on raw records too
fetch logs, from: now()-30m
| filter project == "TonyStark" and appname == "PAN-OS" and contains(content, ",TRAFFIC,end,")   // ✏️ change "TonyStark" to your project name
| fieldsAdd action = splitString(content, ",")[31]
| summarize sessions = count(), by: { action }

fetch logs, from: now()-30m
| filter project == "TonyStark" and isNotNull(bch_access_key_id)   // ✏️ change "TonyStark" to your project name
| summarize sightings = count(), by: { bch_access_key_id }
